INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   2,   1, 'The heavens and the earth were finished, and all their vast array.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   2,   1, 'The heavens, the earth, and all their vast array were finished.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   2,   2, 'On the seventh day God finished his work which he had made; and he rested on the seventh day from all his work which he had made.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   2,   2, 'On the seventh day God finished his work which he had done; and he rested on the seventh day from all his work which he had done.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   2,   3, 'God blessed the seventh day, and made it holy, because he rested in it from all his work which he had created and made.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   2,   3, 'God blessed the seventh day, and made it holy, because he rested in it from all his work of creation which he had done.');
-
-
-
-
-
