INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   6,   1, 'It happened, when men began to multiply on the surface of the ground, and daughters were born to them,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   6,   1, 'When men began to multiply on the surface of the ground, and daughters were born to them,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   6,   2, 'that God\'s sons saw that men\'s daughters were beautiful, and they took for themselves wives of all that they chose.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   6,   2, 'God\'s sons saw that men\'s daughters were beautiful, and they took any that they wanted for themselves as wives.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',   6,   3, 'ForeverOne said, \"My Spirit will not strive with man forever, because he also is flesh; yet will his days be one hundred twenty years.\"');
