INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  21,  26, 'Abimelech said, \"I don\'t know who has done this thing. Neither did you tell me, neither did I hear of it, until today.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  21,  26, 'Abimelech said, \"I don\'t know who has done this thing. You didn\'t tell me, and I didn\'t hear of it until today.\"');
