INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  10, 'Abraham stretched forth his hand, and took the knife to kill his son.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  10, 'Abraham stretched out his hand, and took the knife to kill his son.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  11, 'The angel of ForeverOne called to him out of the sky, and said, \"Abraham, Abraham!\" He said, \"Here I am.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  11, 'ForeverOne\'s angel called to him out of the sky, and said, \"Abraham, Abraham!\" He said, \"Here I am.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  12, 'He said, \"Don\'t lay your hand on the boy, neither do anything to him. For now I know that you fear God, since you have not withheld your son, your only son, from me.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  12, 'He said, \"Don\'t lay your hand on the boy or do anything to him. For now I know that you fear God, since you have not withheld your son, your only son, from me.\"');
-
