INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  14, 'Abraham called the name of that place ForeverOne Will Provide. As it is said to this day, \"On ForeverOne\'s mountain, it will be provided.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  14, 'Abraham called the name of that place \"ForeverOne Will Provide\". As it is said to this day, \"On ForeverOne\'s mountain, it will be provided.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  15, 'The angel of ForeverOne called to Abraham a second time out of the sky,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  15, 'ForeverOne\'s angel called to Abraham a second time out of the sky,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  16, 'and said, \"I have sworn by myself, says ForeverOne, because you have done this thing, and have not withheld your son, your only son,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  22,  16, 'and said, \"\'I have sworn by myself,\' says ForeverOne, \'because you have done this thing, and have not withheld your son, your only son,');
