INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  24,  40, 'He said to me, \'ForeverOne, before whom I walk, will send his angel with you, and prosper your way. You shall take a wife for my son of my relatives, and of my father\'s house.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  24,  40, 'He said to me, \'ForeverOne, before whom I walk, will send his angel with you, and prosper your way. You shall take a wife for my son from my relatives, and of my father\'s house.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  24,  41, 'Then will you be clear from my oath, when you come to my relatives. If they don\'t give her to you, you shall be clear from my oath.\'');
