INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  26,   3, 'Live in this land, and I will be with you, and will bless you. For to you, and to your offspring, I will give all these lands, and I will establish the oath which I swore to Abraham your father.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  26,   3, 'Live in this land, and I will be with you, and will bless you. For I will give to you, and to your offspring, all these lands, and I will establish the oath which I swore to Abraham your father.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  26,   4, 'I will multiply your offspring as the stars of the sky, and will give to your offspring all these lands. In your offspring will all the nations of the earth be blessed,');
