INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  26,  25, 'He built an altar there, and called on the name of ForeverOne, and pitched his tent there. There Isaac\'s servants dug a well.');
