INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,   2, 'He looked, and behold, a well in the field, and, behold, three flocks of sheep lying there by it. For out of that well they watered the flocks. The stone on the well\'s mouth was large.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,   2, 'He looked, and saw a well in the field, and saw three flocks of sheep lying there by it. For out of that well they watered the flocks. The stone on the well\'s mouth was large.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,   3, 'There all the flocks were gathered. They rolled the stone from the well\'s mouth, and watered the sheep, and put the stone again on the well\'s mouth in its place.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,   3, 'There all the flocks were gathered. They rolled the stone from the well\'s mouth, and watered the sheep, and put the stone back on the well\'s mouth in its place.');
