INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,   8, 'They said, \"We can\'t, until all the flocks are gathered together, and they roll the stone from the well\'s mouth. Then we water the sheep.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,   8, 'They said, \"We can\'t, until all the flocks are gathered together, and they roll the stone from the well\'s mouth. Then we will water the sheep.\"');
