INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  10, 'It happened, when Jacob saw Rachel the daughter of Laban, his mother\'s brother, and the sheep of Laban, his mother\'s brother, that Jacob went near, and rolled the stone from the well\'s mouth, and watered the flock of Laban his mother\'s brother.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  10, 'When Jacob saw Rachel the daughter of Laban, his mother\'s brother, and the sheep of Laban, his mother\'s brother, Jacob went near, and rolled the stone from the well\'s mouth, and watered the flock of Laban his mother\'s brother.');
