INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  12, 'Jacob told Rachel that he was her father\'s brother, and that he was Rebekah\'s son. She ran and told her father.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  12, 'Jacob told Rachel that he was her father\'s relative, and that he was Rebekah\'s son. She ran and told her father.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  13, 'It happened, when Laban heard the news of Jacob, his sister\'s son, that he ran to meet Jacob, and embraced him, and kissed him, and brought him to his house. Jacob told Laban all these things.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  13, 'When Laban heard the news of Jacob, his sister\'s son, he ran to meet Jacob, and embraced him, and kissed him, and brought him to his house. Jacob told Laban all these things.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  14, 'Laban said to him, \"Surely you are my bone and my flesh.\" He lived with him for a month.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  29,  14, 'Laban said to him, \"Surely you are my bone and my flesh.\" Jacob stayed with him for a month.');
