INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  24, 'It happened about three months later, that it was told Judah, saying, \"Tamar, your daughter-in-law, has played the prostitute; and moreover, behold, she is with child by prostitution.\" Judah said, \"Bring her forth, and let her be burnt.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  24, 'About three months later, Judah was told, \"Tamar, your daughter-in-law, has played the prostitute. Moreover, behold, she is with child by prostitution.\" Judah said, \"Bring her out, and let her be burned.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  25, 'When she was brought forth, she sent to her father-in-law, saying, \"By the man, whose these are, I am with child.\" She also said, \"Please discern whose are these--the signet, and the cords, and the staff.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  25, 'When she was brought out, she sent to her father-in-law, saying, \"I am with child by the man who owns these.\" She also said, \"Please discern whose these are- the signet, and the cords, and the staff.\"');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  27, 'It happened in the time of her travail, that behold, twins were in her womb.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  27, 'In the time of her travail, behold, twins were in her womb.');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  29, 'It happened, as he drew back his hand, that behold, his brother came out, and she said, \"Why have you made a breach for yourself?\" Therefore his name was called Perez.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  29, 'As he drew back his hand, behold, his brother came out, and she said, \"Why have you made a breach for yourself?\" Therefore his name was called Perez.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  30, 'Afterward his brother came out, that had the scarlet thread on his hand, and his name was called Zerah.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  38,  30, 'Afterward his brother came out, who had the scarlet thread on his hand, and his name was called Zerah.');
-
