INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   4, 'Joseph found favor in his sight. He ministered to him, and he made him overseer over his house, and all that he had he put into his hand.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   4, 'Joseph found favor in his sight. He ministered to him, and Potiphar made him overseer over his house, and all that he had he put into his hand.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   5, 'It happened from the time that he made him overseer in his house, and over all that he had, that ForeverOne blessed the Egyptian\'s house for Joseph\'s sake; and the blessing of ForeverOne was on all that he had, in the house and in the field.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   5, 'From the time that he made him overseer in his house, and over all that he had, ForeverOne blessed the Egyptian\'s house for Joseph\'s sake. ForeverOne\'s blessing was on all that he had, in the house and in the field.');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   7, 'It happened after these things, that his master\'s wife cast her eyes on Joseph; and she said, \"Lie with me.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   7, 'After these things, his master\'s wife set her eyes on Joseph; and she said, \"Lie with me.\"');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   9, 'He isn\'t greater in this house than I, neither has he kept back anything from me but you, because you are his wife. How then can I do this great wickedness, and sin against God?\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,   9, 'No one is greater in this house than I am, and he has not kept back anything from me but you, because you are his wife. How then can I do this great wickedness, and sin against God?\"');
-
