INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  14, 'she called to the men of her house, and spoke to them, saying, \"Behold, he has brought in a Hebrew to us to mock us. He came in to me to lie with me, and I cried with a loud voice.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  14, 'she called to the men of her house, and spoke to them, saying, \"Behold, he has brought a Hebrew in to us to mock us. He came in to me to lie with me, and I cried with a loud voice.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  15, 'It happened, when he heard that I lifted up my voice and cried, that he left his garment by me, and ran outside.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  15, 'When he heard that I lifted up my voice and cried, he left his garment by me, and ran outside.\"');
