INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  18, 'and it happened, as I lifted up my voice and cried, that he left his garment by me, and ran outside.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  18, 'and as I lifted up my voice and cried, he left his garment by me, and ran outside.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  19, 'It happened, when his master heard the words of his wife, which she spoke to him, saying, \"This is what your servant did to me,\" that his wrath was kindled.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  39,  19, 'When his master heard the words of his wife, which she spoke to him, saying, \"This is what your servant did to me,\" his wrath was kindled.');
