INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  41,  42, 'Pharaoh took off his signet ring from his hand, and put it on Joseph\'s hand, and arrayed him in robes of fine linen, and put a gold chain about his neck,');
