INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  41,  44, 'Pharaoh said to Joseph, \"I am Pharaoh, and without you shall no man lift up his hand or his foot in all the land of Egypt.\"');
