INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('GEN',  44,  15, 'Joseph said to them, \"What deed is this that you have done? Don\'t you know that such a man as I can indeed divine?\"');
