INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   2,  23, 'It happened in the course of those many days, that the king of Egypt died, and the children of Israel sighed because of the slavery, and they cried, and their cry came up to God because of the slavery.');
