INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   2, 'The angel of ForeverOne appeared to him in a flame of fire out of the midst of a bush. He looked, and behold, the bush burned with fire, and the bush was not consumed.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   2, 'ForeverOne\'s angel appeared to him in a flame of fire out of the middle of a bush. He looked, and behold, the bush burned with fire, and the bush was not consumed.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   3, 'Moses said, \"I will turn aside now, and see this great sight, why the bush is not burnt.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   3, 'Moses said, \"I will go now, and see this great sight, why the bush is not burned.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   4, 'When ForeverOne saw that he turned aside to see, God called to him out of the midst of the bush, and said, \"Moses! Moses!\" He said, \"Here I am.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   4, 'When ForeverOne saw that he came over to see, God called to him out of the middle of the bush, and said, \"Moses! Moses!\" He said, \"Here I am.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   5, 'He said, \"Don\'t come close. Take your sandals off of your feet, for the place you are standing on is holy ground.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   5, 'He said, \"Don\'t come close. Take off your sandals, for the place you are standing on is holy ground.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   6, 'Moreover he said, \"I am the God of your father, the God of Abraham, the God of Isaac, and the God of Jacob.\" Moses hid his face; for he was afraid to look at God.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   3,   6, 'Moreover he said, \"I am the God of your father, the God of Abraham, the God of Isaac, and the God of Jacob.\" Moses hid his face because he was afraid to look at God.');
