INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   4,  22, 'You shall tell Pharaoh, \'Thus says ForeverOne, Israel is my son, my firstborn,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   4,  22, 'You shall tell Pharaoh, \'ForeverOne says, Israel is my son, my firstborn,');
