INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   6,  28, 'It happened on the day when ForeverOne spoke to Moses in the land of Egypt,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   6,  28, 'On the day when ForeverOne spoke to Moses in the land of Egypt,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   6,  29, 'that ForeverOne spoke to Moses, saying, \"I am ForeverOne. Speak to Pharaoh king of Egypt all that I speak to you.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',   6,  29, 'ForeverOne said to Moses, \"I am ForeverOne. Tell Pharaoh king of Egypt all that I tell you.\"');
