INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  16,  20, 'Notwithstanding they didn\'t listen to Moses, but some of them left of it until the morning, and it bred worms, and became foul: and Moses was angry with them.');
