INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  28,  16, 'It shall be square and folded double; a span shall be its length of it, and a span its breadth.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  28,  16, 'It shall be square and folded double; a span shall be its length, and a span its width.');
-
-
