INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  30,   6, 'You shall put it before the veil that is by the ark of the testimony, before the mercy seat that is over the testimony, where I will meet with you.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  30,   6, 'You shall put it before the veil that is by the ark of the covenant, before the mercy seat that is over the covenant, where I will meet with you.');
