INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   1, 'ForeverOne said to Moses, \"Chisel two stone tablets like the first: and I will write on the tablets the words that were on the first tablets, which you broke.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   1, 'ForeverOne said to Moses, \"Chisel two stone tablets like the first. I will write on the tablets the words that were on the first tablets, which you broke.');
-
