INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   3, 'No one shall come up with you; neither let anyone be seen throughout all the mountain; neither let the flocks nor herds feed before that mountain.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   3, 'No one shall come up with you or be seen anywhere on the mountain. Do not let the flocks or herds graze in front of that mountain.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   4, 'He chiseled two tablets of stone like the first; and Moses rose up early in the morning, and went up to Mount Sinai, as ForeverOne had commanded him, and took in his hand two stone tablets.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   4, 'He chiseled two tablets of stone like the first; then Moses rose up early in the morning, and went up to Mount Sinai, as ForeverOne had commanded him, and took in his hand two stone tablets.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   5, 'ForeverOne descended in the cloud, and stood with him there, and proclaimed the name of ForeverOne.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   5, 'ForeverOne descended in the cloud, and stood with him there, and proclaimed ForeverOne\'s name.');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   7, 'keeping loving kindness for thousands, forgiving iniquity and disobedience and sin; and that will by no means clear the guilty, visiting the iniquity of the fathers on the children, and on the children\'s children, on the third and on the fourth generation.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  34,   7, 'keeping loving kindness for thousands, forgiving iniquity and disobedience and sin; and who will by no means clear the guilty, visiting the iniquity of the fathers on the children, and on the children\'s children, on the third and on the fourth generation.\"');
-
