INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('EXO',  35,  21, 'They came, everyone whose heart stirred him up, and everyone whom his spirit made willing, and brought ForeverOne\'s offering, for the work of the Tent of Meeting, and for all of its service, and for the holy garments.');
