--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   1,  14, '\"\'If his offering to ForeverOne is a burnt offering of birds, then he shall offer his offering from turtledoves or of young pigeons.');
