INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  25, 'For whoever eats the fat of the animal, of which men offer an offering made by fire to ForeverOne, even the soul who eats it shall be cut off from his people.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  25, 'For whoever eats the fat of the animal which men offer as an offering made by fire to ForeverOne, even the soul who eats it shall be cut off from his people.');
