INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  35, 'This is the anointing portion of Aaron, and the anointing portion of his sons, out of the offerings of ForeverOne made by fire, in the day when he presented them to minister to ForeverOne in the priest\'s office;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  35, 'This is the consecrated portion of Aaron, and the consecrated portion of his sons, out of the offerings of ForeverOne made by fire, in the day when he presented them to minister to ForeverOne in the priest\'s office;');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  37, 'This is the law of the burnt offering, of the meal offering, and of the sin offering, and of the trespass offering, and of the consecration, and of the sacrifice of peace offerings;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  37, 'This is the law of the burnt offering, the meal offering, the sin offering, the trespass offering, the consecration, and the sacrifice of peace offerings');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  38, 'which ForeverOne commanded Moses in Mount Sinai, in the day that he commanded the children of Israel to offer their offerings to ForeverOne, in the wilderness of Sinai.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',   7,  38, 'which ForeverOne commanded Moses in Mount Sinai in the day that he commanded the children of Israel to offer their offerings to ForeverOne, in the wilderness of Sinai.');
