INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  14,  49, 'To cleanse the house he shall take two birds, and cedar wood, and scarlet, and hyssop.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  14,  49, 'To cleanse the house he shall take two birds, cedar wood, scarlet, and hyssop.');
-
