INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  25,  17, 'You shall not wrong one another; but you shall fear your God: for I am ForeverOne your God.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  25,  17, 'You shall not wrong one another, but you shall fear your God; for I am ForeverOne your God.');
-
-
-
-
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  25,  21, 'then I will command my blessing on you in the sixth year, and it shall bring forth fruit for the three years.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  25,  21, 'then I will command my blessing on you in the sixth year, and it shall bear fruit for the three years.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  25,  22, 'You shall sow the eighth year, and eat of the fruits, the old store; until the ninth year, until its fruits come in, you shall eat the old store.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  25,  22, 'You shall sow the eighth year, and eat of the fruits from the old store until the ninth year. Until its fruits come in, you shall eat the old store.');
