INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  14, '\"\'When a man dedicates his house to be holy to ForeverOne, then the priest shall evaluate it, whether it is good or bad: as the priest shall evaluate it, so shall it stand.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  14, '\"\'When a man dedicates his house to be holy to ForeverOne, then the priest shall evaluate it, whether it is good or bad. As the priest evaluates it, so it shall stand.');
