INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  16, '\"\'If a man dedicates to ForeverOne part of the field of his possession, then your valuation shall be according to the offspring for it: the sowing of a homer of barley shall be valued at fifty shekels of silver.');
