INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  26, '\"\'Only the firstborn among animals, which is made a firstborn to ForeverOne, no man may dedicate it; whether an ox or sheep, it is ForeverOne\'s.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  26, '\"\'However the firstborn among animals, which belongs to ForeverOne as a firstborn, no man may dedicate, whether an ox or a sheep. It is ForeverOne\'s.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  27, 'If it is an unclean animal, then he shall buy it back according to your valuation, and shall add to it the fifth part of it: or if it isn\'t redeemed, then it shall be sold according to your valuation.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  27, 'If it is an unclean animal, then he shall buy it back according to your valuation, and shall add to it the fifth part of it; or if it isn\'t redeemed, then it shall be sold according to your valuation.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  28, '\"\'Notwithstanding, no devoted thing, that a man shall devote to ForeverOne of all that he has, whether of man or animal, or of the field of his possession, shall be sold or redeemed: every devoted thing is most holy to ForeverOne.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  28, '\"\'Notwithstanding, no devoted thing that a man devotes to ForeverOne of all that he has, whether of man or animal, or of the field of his possession, shall be sold or redeemed. Everything that is permanently devoted is most holy to ForeverOne.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  29, '\"\'No one devoted, who shall be devoted from among men, shall be ransomed; he shall surely be put to death.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('LEV',  27,  29, '\"\'No one devoted to destruction, who shall be devoted from among men, shall be ransomed. He shall surely be put to death.');
