INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   1,  19, 'As ForeverOne commanded Moses, so he numbered them in the wilderness of Sinai.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   1,  19, 'As ForeverOne commanded Moses, so he counted them in the wilderness of Sinai.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   1,  20, 'The children of Reuben, Israel\'s firstborn, their generations, by their families, by their fathers\' houses, according to the number of the names, one by one, every male from twenty years old and upward, all who were able to go out to war;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   1,  20, 'The children of Reuben, Israel\'s firstborn, their generations, by their families, by their fathers\' houses, according to the number of the names, one by one, every male from twenty years old and upward, all who were able to go out to war:');
