INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   2,   2, '\"The children of Israel shall encamp every man by his own standard, with the banners of their fathers\' houses: at a distance from the Tent of Meeting shall they encamp around it.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   2,   2, '\"The children of Israel shall encamp every man by his own standard, with the banners of their fathers\' houses. They shall encamp around the Tent of Meeting at a distance from it.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   2,   3, 'Those who encamp on the east side toward the sunrise shall be of the standard of the camp of Judah, according to their divisions: and the prince of the children of Judah shall be Nahshon the son of Amminadab.');
