INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   2,  17, '\"Then the Tent of Meeting shall set out, with the camp of the Levites in the midst of the camps. As they encamp, so shall they set out, every man in his place, by their standards.');
