INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   3,  40, 'ForeverOne said to Moses, \"Number all the firstborn males of the children of Israel from a month old and upward, and take the number of their names.');
