INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   8,   4, 'This was the workmanship of the lampstand, beaten work of gold. From its base to its flowers, it was beaten work: according to the pattern which ForeverOne had shown Moses, so he made the lampstand.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',   8,   4, 'This was the workmanship of the lampstand, beaten work of gold. From its base to its flowers, it was beaten work. He made the lampstand according to the pattern which ForeverOne had shown Moses.');
