INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   1, 'The people were complaining in the ears of ForeverOne. When ForeverOne heard it, his anger was kindled; and ForeverOne\'s fire burnt among them, and consumed some of the outskirts of the camp.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   1, 'The people were complaining in the ears of ForeverOne. When ForeverOne heard it, his anger burned; and ForeverOne\'s fire burned among them, and consumed some of the outskirts of the camp.');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   3, 'The name of that place was called Taberah, because ForeverOne\'s fire burnt among them.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   3, 'The name of that place was called Taberah, because ForeverOne\'s fire burned among them.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   4, 'The mixed multitude that was among them lusted exceedingly: and the children of Israel also wept again, and said, \"Who will give us flesh to eat?');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   4, 'The mixed multitude that was among them lusted exceedingly; and the children of Israel also wept again, and said, \"Who will give us meat to eat?');
