INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   7, 'The manna was like coriander offspring, and its appearance like the appearance of bdellium.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  11,   7, 'The manna was like coriander offspring, and it looked like bdellium.');
