INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  12,   6, 'He said, \"Hear now my words. If there is a prophet among you, I ForeverOne will make myself known to him in a vision. I will speak with him in a dream.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  12,   6, 'He said, \"Now hear my words. If there is a prophet among you, I, ForeverOne, will make myself known to him in a vision. I will speak with him in a dream.');
