INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  13,  23, 'They came to the valley of Eshcol, and cut down from there a branch with one cluster of grapes, and they bore it on a staff between two; [they brought] also of the pomegranates, and of the figs.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  13,  23, 'They came to the valley of Eshcol, and cut down from there a branch with one cluster of grapes, and they bore it on a staff between two. They also brought some of the pomegranates and figs.');
