INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  22, 'They traveled from Kadesh: and the children of Israel, even the whole congregation, came to Mount Hor.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  22, 'They traveled from Kadesh, and the children of Israel, even the whole congregation, came to Mount Hor.');
-
-
