INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  26, 'and strip Aaron of his garments, and put them on Eleazar his son: and Aaron shall be gathered [to his people], and shall die there.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  26, 'and strip Aaron of his garments, and put them on Eleazar his son. Aaron shall be gathered, and shall die there.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  27, 'Moses did as ForeverOne commanded: and they went up into Mount Hor in the sight of all the congregation.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  27, 'Moses did as ForeverOne commanded. They went up onto Mount Hor in the sight of all the congregation.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  28, 'Moses stripped Aaron of his garments, and put them on Eleazar his son; and Aaron died there on the top of the mountain: and Moses and Eleazar came down from the mountain.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  20,  28, 'Moses stripped Aaron of his garments, and put them on Eleazar his son. Aaron died there on the top of the mountain, and Moses and Eleazar came down from the mountain.');
