-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  38, 'The cattle were thirty-six thousand; of which ForeverOne\'s tribute was seventy-two.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  38, 'The cattle were thirty-six thousand, of which ForeverOne\'s tribute was seventy-two.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  39, 'The donkeys were thirty thousand five hundred; of which ForeverOne\'s tribute was sixty-one.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  39, 'The donkeys were thirty thousand five hundred, of which ForeverOne\'s tribute was sixty-one.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  40, 'The persons were sixteen thousand; of whom ForeverOne\'s tribute was thirty-two persons.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  40, 'The persons were sixteen thousand, of whom ForeverOne\'s tribute was thirty-two persons.');
