--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  42, 'Of the children of Israel\'s half, which Moses divided off from the men who fought');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  43, '(now the congregation\'s half was three hundred thirty-seven thousand five hundred sheep,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  43, 'now the congregation\'s half was three hundred thirty-seven thousand five hundred sheep,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  44, 'and thirty-six thousand head of cattle,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  44, 'thirty-six thousand head of cattle,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  45, 'and thirty thousand five hundred donkeys,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  31,  45, 'thirty thousand five hundred donkeys,');
