INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  33,  38, 'Aaron the priest went up into Mount Hor at the commandment of ForeverOne, and died there, in the fortieth year after the children of Israel were come out of the land of Egypt, in the fifth month, on the first day of the month.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NUM',  33,  38, 'Aaron the priest went up into Mount Hor at the commandment of ForeverOne and died there, in the fortieth year after the children of Israel had come out of the land of Egypt, in the fifth month, on the first day of the month.');
