INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  14,  11, 'As yet I am as strong today as I was in the day that Moses sent me: as my strength was then, even so is my strength now for war, to go out and to come in.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  14,  11, 'As yet I am as strong today as I was in the day that Moses sent me. As my strength was then, even so is my strength now for war, to go out and to come in.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  14,  12, 'Now therefore give me this hill country, of which ForeverOne spoke in that day; for you heard in that day how the Anakim were there, and great and fortified cities. It may be that ForeverOne will be with me, and I shall drive them out, as ForeverOne spoke.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  14,  12, 'Now therefore give me this hill country, of which ForeverOne spoke in that day; for you heard in that day how the Anakim were there, and great and fortified cities. It may be that ForeverOne will be with me, and I shall drive them out, as ForeverOne said.\"');
