INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  13, 'It happened, when the children of Israel had grown strong, that they put the Canaanites to forced labor, and didn\'t utterly drive them out.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  13, 'When the children of Israel had grown strong, they put the Canaanites to forced labor, and didn\'t utterly drive them out.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  14, 'The children of Joseph spoke to Joshua, saying, \"Why have you given me just one lot and one part for an inheritance, since I am a great people, because ForeverOne has blessed me so far?\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  14, 'The children of Joseph spoke to Joshua, saying, \"Why have you given me just one lot and one part for an inheritance, since we are a numerous people, because ForeverOne has blessed us so far?\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  15, 'Joshua said to them, \"If you are a great people, go up to the forest, and clear land for yourself there in the land of the Perizzites and of the Rephaim; since the hill country of Ephraim is too narrow for you.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  15, 'Joshua said to them, \"If you are a numerous people, go up to the forest, and clear land for yourself there in the land of the Perizzites and of the Rephaim, since the hill country of Ephraim is too narrow for you.\"');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  17, 'Joshua spoke to the house of Joseph, even to Ephraim and to Manasseh, saying, \"You are a great people, and have great power. You shall not have one lot only;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  17,  17, 'Joshua spoke to the house of Joseph, that is, to Ephraim and to Manasseh, saying, \"You are a numerous people, and have great power. You shall not have one lot only;');
