INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  21,  41, 'All the cities of the Levites in the midst of the possession of the children of Israel were forty-eight cities with their suburbs.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  21,  41, 'All the cities of the Levites among the possessions of the children of Israel were forty-eight cities with their pasture lands.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  21,  42, 'Each of these cities included their suburbs around them. It was this way with all these cities.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  21,  42, 'Each of these cities included their pasture lands around them. It was this way with all these cities.');
