INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  23,   1, 'It happened after many days, when ForeverOne had given rest to Israel from their enemies all around, and Joshua was old and well advanced in years,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  23,   1, 'After many days, when ForeverOne had given rest to Israel from their enemies all around, and Joshua was old and well advanced in years,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  23,   2, 'that Joshua called for all Israel, for their elders and for their heads, and for their judges and for their officers, and said to them, \"I am old and well advanced in years.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOS',  23,   2, 'Joshua called for all Israel, for their elders and for their heads, and for their judges and for their officers, and said to them, \"I am old and well advanced in years.');
-
