-
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  12, 'He made darkness pavilions around himself: gathering of waters, and thick clouds of the skies.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  12, 'He made darkness a shelter around himself, gathering of waters, and thick clouds of the skies.');
