INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  15, 'He sent out arrows, and scattered them; lightning, and confused them.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  15, 'He sent out arrows and scattered them, lightning and confused them.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  16, 'Then the channels of the sea appeared. The foundations of the world were laid bare by the rebuke of ForeverOne, At the blast of the breath of his nostrils.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  16, 'Then the channels of the sea appeared. The foundations of the world were laid bare by ForeverOne\'s rebuke, at the blast of the breath of his nostrils.');
