INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  22, 'For I have kept the ways of ForeverOne, and have not wickedly departed from my God.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  22, 'For I have kept ForeverOne\'s ways, and have not wickedly departed from my God.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  23, 'For all his ordinances were before me. As for his statutes, I did not depart from them.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  23, 'For all his ordinances were before me. As for his statutes, I didn\'t depart from them.');
