INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  28, 'You will save the afflicted people, But your eyes are on the haughty, that you may bring them down.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  28, 'You will save the afflicted people, but your eyes are on the arrogant, that you may bring them down.');
