INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  34, 'He makes his feet like hinds\' [feet], and sets me on my high places.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  34, 'He makes his feet like hinds\' feet, and sets me on my high places.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  35, 'He teaches my hands to war, so that my arms bend a bow of brass.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  35, 'He teaches my hands to war, so that my arms bend a bow of bronze.');
