INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  50, 'Therefore I will give thanks to you, ForeverOne, among the nations. Will sing praises to your name.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  50, 'Therefore I will give thanks to you, ForeverOne, among the nations, and will sing praises to your name.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  51, 'He gives great deliverance to his king, and shows loving kindness to his anointed, to David and to his offspring, forevermore.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  22,  51, 'He gives great deliverance to his king, and shows loving kindness to his anointed, to David and to his offspring, forever more.\"');
