INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  23,   2, '\"The Spirit of ForeverOne spoke by me. His word was on my tongue.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('2SA',  23,   2, '\"ForeverOne\'s Spirit spoke by me. His word was on my tongue.');
-
