INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   4, 'six were born to him in Hebron; and there he reigned seven years and six months. In Jerusalem he reigned thirty-three years;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   4, 'six were born to him in Hebron; and he reigned there seven years and six months. He reigned thirty-three years in Jerusalem;');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   5, 'and these were born to him in Jerusalem: Shimea, and Shobab, and Nathan, and Solomon, four, of Bathshua the daughter of Ammiel;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   5, 'and these were born to him in Jerusalem: Shimea, Shobab, Nathan, and Solomon, four, by Bathshua the daughter of Ammiel;');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   6, 'and Ibhar, and Elishama, and Eliphelet,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   6, 'and Ibhar, Elishama, Eliphelet,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   7, 'and Nogah, and Nepheg, and Japhia,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   7, 'Nogah, Nepheg, Japhia,');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   8, 'and Elishama, and Eliada, and Eliphelet, nine.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   8, 'Elishama, Eliada, and Eliphelet, nine.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   9, 'All these were the sons of David, besides the sons of the concubines; and Tamar was their sister.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   3,   9, 'All these were the sons of David, in addition to the sons of the concubines; and Tamar was their sister.');
