INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   5, 'and Abishua became the father of Bukki, and Bukki became the father of Uzzi,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   5, 'Abishua became the father of Bukki. Bukki became the father of Uzzi.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   6, 'and Uzzi became the father of Zerahiah, and Zerahiah became the father of Meraioth,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   6, 'Uzzi became the father of Zerahiah. Zerahiah became the father of Meraioth.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   7, 'Meraioth became the father of Amariah, and Amariah became the father of Ahitub,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   7, 'Meraioth became the father of Amariah. Amariah became the father of Ahitub.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   8, 'and Ahitub became the father of Zadok, and Zadok became the father of Ahimaaz,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   8, 'Ahitub became the father of Zadok. Zadok became the father of Ahimaaz.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   9, 'and Ahimaaz became the father of Azariah, and Azariah became the father of Johanan,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,   9, 'Ahimaaz became the father of Azariah. Azariah became the father of Johanan.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  10, 'and Johanan became the father of Azariah, (he it is who executed the priest\'s office in the house that Solomon built in Jerusalem),');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  10, 'Johanan became the father of Azariah, who executed the priest\'s office in the house that Solomon built in Jerusalem.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  11, 'and Azariah became the father of Amariah, and Amariah became the father of Ahitub,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  11, 'Azariah became the father of Amariah. Amariah became the father of Ahitub.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  12, 'and Ahitub became the father of Zadok, and Zadok became the father of Shallum,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  12, 'Ahitub became the father of Zadok. Zadok became the father of Shallum.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  13, 'and Shallum became the father of Hilkiah, and Hilkiah became the father of Azariah,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  13, 'Shallum became the father of Hilkiah. Hilkiah became the father of Azariah.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  14, 'and Azariah became the father of Seraiah, and Seraiah became the father of Jehozadak;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  14, 'Azariah became the father of Seraiah. Seraiah became the father of Jehozadak.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  15, 'Jehozadak went [into captivity], when ForeverOne carried away Judah and Jerusalem by the hand of Nebuchadnezzar.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  15, 'Jehozadak went into captivity when ForeverOne carried Judah and Jerusalem away by the hand of Nebuchadnezzar.');
