INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  31, 'These are they whom David set over the service of song in the house of ForeverOne, after that the ark had rest.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  31, 'These are they whom David set over the service of song in ForeverOne\'s house after the ark came to rest there.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  32, 'They ministered with song before the tabernacle of the Tent of Meeting, until Solomon had built the house of ForeverOne in Jerusalem: and they waited on their office according to their order.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',   6,  32, 'They ministered with song before the tabernacle of the Tent of Meeting until Solomon had built ForeverOne\'s house in Jerusalem. They performed the duties of their office according to their order.');
