INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  11,  39, 'Zelek the Ammonite, Naharai the Berothite, the armor bearer of Joab the son of Zeruiah,');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  11,  39, 'Zelek the Ammonite, Naharai the Berothite (the armor bearer of Joab the son of Zeruiah),');
