INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  16,  28, 'Ascribe to ForeverOne, you relatives of the peoples, ascribe to ForeverOne glory and strength!');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  16,  28, 'Ascribe to ForeverOne, you families of the peoples, ascribe to ForeverOne glory and strength!');
