INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,   8, 'The sons of Ladan: Jehiel the chief, and Zetham, and Joel, three.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,   8, 'The sons of Ladan: Jehiel the chief, Zetham, and Joel, three.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,   9, 'The sons of Shimei: Shelomoth, and Haziel, and Haran, three. These were the heads of the fathers\' [houses] of Ladan.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,   9, 'The sons of Shimei: Shelomoth, Haziel, and Haran, three. These were the heads of the fathers\' households of Ladan.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,  10, 'The sons of Shimei: Jahath, Zina, and Jeush, and Beriah. These four were the sons of Shimei.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,  10, 'The sons of Shimei: Jahath, Zina, Jeush, and Beriah. These four were the sons of Shimei.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,  11, 'Jahath was the chief, and Zizah the second: but Jeush and Beriah didn\'t have many sons; therefore they became a fathers\' house in one reckoning.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,  11, 'Jahath was the chief, and Zizah the second; but Jeush and Beriah didn\'t have many sons; therefore they became a fathers\' house in one reckoning.');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,  13, 'The sons of Amram: Aaron and Moses; and Aaron was separated, that he should sanctify the most holy things, he and his sons, forever, to burn incense before ForeverOne, to minister to him, and to bless in his name, forever.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  23,  13, 'The sons of Amram: Aaron and Moses; and Aaron was separated that he should sanctify the most holy things, he and his sons forever, to burn incense before ForeverOne, to minister to him, and to bless in his name forever.');
