INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  24,  18, 'the twenty-third to Delaiah, the twenty-fourth to Maaziah.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  24,  18, 'the twenty-third to Delaiah, and the twenty-fourth to Maaziah.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  24,  19, 'This was the ordering of them in their service, to come into the house of ForeverOne according to the ordinance [given] to them by Aaron their father, as ForeverOne, the God of Israel, had commanded him.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('1CH',  24,  19, 'This was their ordering in their service, to come into ForeverOne\'s house according to the ordinance given to them by Aaron their father, as ForeverOne, the God of Israel, had commanded him.');
