INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NEH',  10,   8, 'Maaziah, Bilgai, Shemaiah; these were the priests.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NEH',  10,   8, 'Maaziah, Bilgai, and Shemaiah. These were the priests.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NEH',  10,   9, 'The Levites: namely, Jeshua the son of Azaniah, Binnui of the sons of Henadad, Kadmiel;');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NEH',  10,   9, 'The Levites: Jeshua the son of Azaniah, Binnui of the sons of Henadad, Kadmiel;');
