-
-
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NEH',  11,  36, 'Of the Levites, certain divisions in Judah [were joined] to Benjamin.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('NEH',  11,  36, 'Of the Levites, certain divisions in Judah settled in Benjamin\'s territory.');
-
