INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   1,  21, 'He said, \"Naked I came out of my mother\'s womb, and naked shall I return there. ForeverOne gave, and ForeverOne has taken away. Blessed be the name of ForeverOne.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   1,  21, 'He said, \"Naked I came out of my mother\'s womb, and naked will I return there. ForeverOne gave, and ForeverOne has taken away. Blessed be ForeverOne\'s name.\"');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   1,  22, 'In all this, Job did not sin, nor charge God with wrongdoing.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   1,  22, 'In all this, Job didn\'t sin, nor charge God with wrongdoing.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   1, 'Again it happened on the day when the God\'s sons came to present themselves before ForeverOne, that Satan came also among them to present himself before ForeverOne.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   1, 'Again, on the day when God\'s sons came to present themselves before ForeverOne, Satan came also among them to present himself before ForeverOne.');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   3, 'ForeverOne said to Satan, \"Have you considered my servant Job? For there is none like him in the earth, a blameless and an upright man, one who fears God, and turns away from evil. He still maintains his integrity, although you incited me against him, to ruin him without cause.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   3, 'ForeverOne said to Satan, \"Have you considered my servant Job? For there is no one like him in the earth, a blameless and an upright man, one who fears God, and turns away from evil. He still maintains his integrity, although you incited me against him, to ruin him without cause.\"');
-
-
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   5, 'But put forth your hand now, and touch his bone and his flesh, and he will renounce you to your face.\"');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   5, 'But stretch out your hand now, and touch his bone and his flesh, and he will renounce you to your face.\"');
-
