INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   7, 'So Satan went forth from the presence of ForeverOne, and struck Job with painful sores from the sole of his foot to his head.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',   2,   7, 'So Satan went out from the presence of ForeverOne, and struck Job with painful sores from the sole of his foot to his head.');
