--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  15,  29, 'He will not be rich, neither will his substance continue, neither will their possessions be extended on the earth.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  15,  30, 'He shall not depart out of darkness. The flame shall dry up his branches. By the breath of God\'s mouth shall he go away.');
