INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  17,   3, '\"Now give a pledge, be collateral for me with yourself. Who is there who will strike hands with me?');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  17,   3, '\"Now give a pledge. Be collateral for me with yourself. Who is there who will strike hands with me?');
