INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   2, 'Then the wrath of Elihu the son of Barachel, the Buzite, of the family of Ram, was kindled against Job. His wrath was kindled because he justified himself rather than God.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   2, 'Then the wrath of Elihu the son of Barachel, the Buzite, of the family of Ram, was kindled against Job. His wrath was kindled because he justified himself rather than God.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   3, 'Also his wrath was kindled against his three friends, because they had found no answer, and yet had condemned Job.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   3, 'Also his wrath was kindled against his three friends, because they had found no answer, and yet had condemned Job.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   4, 'Now Elihu had waited to speak to Job, because they were elder than he.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   4, 'Now Elihu had waited to speak to Job, because they were elder than he.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   5, 'When Elihu saw that there was no answer in the mouth of these three men, his wrath was kindled.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   5, 'When Elihu saw that there was no answer in the mouth of these three men, his wrath was kindled.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   6, 'Elihu the son of Barachel the Buzite answered, \"I am young, and you are very old; Therefore I held back, and didn\'t dare show you my opinion.');
