INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   7, 'I said, \'Days should speak, and multitude of years should teach wisdom.\'');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   7, 'I said, \'Days should speak, and multitude of years should teach wisdom.\'');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   8, 'But there is a spirit in man, and the breath of the Almighty gives them understanding.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   8, 'But there is a spirit in man, and the Spirit of the Almighty gives them understanding.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,   9, 'It is not the great who are wise, nor the aged who understand justice.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,   9, 'It is not the great who are wise, nor the aged who understand justice.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  10, 'Therefore I said, \'Listen to me; I also will show my opinion.\'');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  10, 'Therefore I said, \'Listen to me; I also will show my opinion.\'');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  11, '\"Behold, I waited for your words, and I listened for your reasoning, while you searched out what to say.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  11, '\"Behold, I waited for your words, and I listened for your reasoning, while you searched out what to say.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  12, 'Yes, I gave you my full attention, but there was no one who convinced Job, or who answered his words, among you.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  12, 'Yes, I gave you my full attention, but there was no one who convinced Job, or who answered his words, among you.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  13, 'Beware lest you say, \'We have found wisdom, God may refute him, not man;\'');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  13, 'Beware lest you say, \'We have found wisdom. God may refute him, not man;\'');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  14, 'for he has not directed his words against me; neither will I answer him with your speeches.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  14, 'for he has not directed his words against me; neither will I answer him with your speeches.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  15, '\"They are amazed. They answer no more. They don\'t have a word to say.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  15, '\"They are amazed. They answer no more. They don\'t have a word to say.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  16, 'Shall I wait, because they don\'t speak, because they stand still, and answer no more?');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  16, 'Shall I wait, because they don\'t speak, because they stand still, and answer no more?');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  17, 'I also will answer my part, and I also will show my opinion.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  17, 'I also will answer my part, and I also will show my opinion.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  18, 'For I am full of words. The spirit within me constrains me.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  18, 'For I am full of words. The spirit within me constrains me.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  19, 'Behold, my breast is as wine which has no vent; like new wineskins it is ready to burst.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  19, 'Behold, my breast is as wine which has no vent; like new wineskins it is ready to burst.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  20, 'I will speak, that I may be refreshed. I will open my lips and answer.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  20, 'I will speak, that I may be refreshed. I will open my lips and answer.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  21, 'Please don\'t let me respect any man\'s person, neither will I give flattering titles to any man.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  21, 'Please don\'t let me respect any man\'s person, neither will I give flattering titles to any man.');
INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  32,  22, 'For I don\'t know how to give flattering titles; or else my Maker would soon take me away.');
--INSERT INTO `verses` (`bookCode`, `chapter`, `verseNumber`, `verseText`) VALUES ('JOB',  31,  22, 'For I don\'t know how to give flattering titles, or else my Maker would soon take me away.');
